pe\":\"number\",\"step\":\"any\"},{\"id\":\"waktu_retensi\",\"label\":\"Rt (menit)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"respon_puncak\",\"label\":\"Respon Puncak\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"lambda_nm\",\"label\":\"λ (nm)\",\"type\":\"number\",\"step\":\"any\"}],\"default_rows\":[{\"tahap\":\"Baku Induk\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"25\",\"konsentrasi\":\"\",\"vol_injeksi\":\"\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"\"},{\"tahap\":\"Bk Kerja 1\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"0.0125\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 2\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"0.25\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 3\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"0.75\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 4\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"1.25\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 5\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"1.75\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 6\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"2.25\\/10\",\"konsentrasi\":\"\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Bk Kerja 7\",\"wadah_za