umber\",\"step\":\"any\"},{\"id\":\"faktor_pengenceran\",\"label\":\"Faktor Pengenceran (mL)\",\"type\":\"text\",\"step\":\"any\"},{\"id\":\"vol_injeksi\",\"label\":\"Vol. Inj (µL)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"waktu_retensi\",\"label\":\"Rt (menit)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"respon_puncak\",\"label\":\"Respon Puncak\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"lambda_nm\",\"label\":\"λ (nm)\",\"type\":\"number\",\"step\":\"any\"}],\"default_rows\":[{\"tahap\":\"Spiked Sample 1\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"10\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"},{\"tahap\":\"Spiked Sample 2\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"10\",\"vol_injeksi\":\"20\",\"waktu_retensi\":\"\",\"respon_puncak\":\"\",\"lambda_nm\":\"312\"}]}]},{\"id\":\"perhitungan_pangan_hplc\",\"title\":\"Perhitungan Kadar, Recovery Spike Duplo, RPD\\/Horwitz, & LOD\\/LOQ\",\"description\":\"Otomatis menghitung x1, x2, Kadar (mg\\/kg), % Recovery 1 & 2, RPD\\/RSD, dan 1\\/2 CV Horwitz. Input LOD & LOQ diisi manual sesuai instrumen.\",\"fields\":[{\"id\":\"x1_sampel\",\"label\":\"x1 Sampel (µg\\/mL)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"x2_sampel\",\"label\":\"x2 Sampel (µg\\/mL)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar1_sampel\",\"label\":\"Kadar Sampel 1 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar2_sampel\",\"label\":\"Kadar Sampel 2 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"rata_kadar_sampel\",\"label\":\"Rata-rata Kadar Tanpa Spike (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"x1_spike\",\"label\":\"x1 Spike (µg\\/mL)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"x2_spike\",\"label\":\"x2 Spike (µg\\/mL)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar1_spike\",\"label\":\"Kadar + Spike 1 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar2_spike\",\"label\":\"Kadar + Spike 2 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"rata_kadar_spike\",\"label\":\"Rata-rata Kadar + Spike (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"recovery_1\",\"label\":\"Recovery 1 (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"recovery_2\",\"label\":\"Recovery 2 (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"syarat_recovery\",\"label\":\"Syarat Recovery (%)\",\"type\":\"text\",\"default\":\"90 - 107 %\"},{\"id\":\"nilai_rpd\",\"label\":\"RPD \\/ RSD (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"syarat_horwitz\",\"label\":\"Syarat RPD (1\\/2 CV Horwitz %)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"lod_nilai\",\"label\":\"Nilai LOD (Angka)\",\"type\":\"number\",\"step\":\"any\",\"placeholder\":\"Contoh: 1.0364\"},{\"id\":\"lod_satuan\",\"label\":\"Satuan LOD\",\"type\":\"text\",\"default\":\"mg\\/kg\"},{\"id\":\"loq_nilai\",\"label\":\"Nilai LOQ (Angka)\",\"type\":\"number\",\"step\":\"any\",\"placeholder\":\"Contoh: 3.4547\"},{\"id\":\"loq_satuan\",\"label\":\"Satuan LOQ\",\"type\":\"text\",\"default\":\"mg\\/kg\"},{\"id\":\"hasil_identifikasi\",\"label\":\"Hasil Uji (Identifikasi)\",\"type\":\"select\",\"options\":[\"-\",\"Positif\",\"Negatif\"],\"default\":\"-\"},{\"id\":\"ketidakpastian_teks\",\"label\":\"Hasil Uji ± Ketidakpastian\",\"type\":\"text\",\"placeholder\":\"Contoh: < LOD atau 97.62 ± 2.10 mg\\/kg\"},{\"id\":\"decision_rule\",\"label\":\"Aturan Keputusan (Decision Rule)\",\"type\":\"select\",\"options\":[\"Simple Acceptance\",\"Guard Band\"],\"default\":\"Simple Acceptance\"}]},{\"id\":\"kesimpulan_legalitas_hplc\",\"title\":\"Pustaka Persyaratan & Legalitas\",\"description\":\"Acuan metode, peraturan batas maksimum BTP, dan tanggal laporan.\",\"fields\":[{\"id\":\"pustaka_metode\",\"label\":\"Pustaka Metode\",\"type\":\"text\",\"default\":\"MA PPOM 53\\/PA\\/16\"},{\"id\":\"pustaka_persyaratan\",\"label\":\"Pustaka Persyaratan\",\"type\":\"text\",\"default\":\"PerBPOM No. 11 Tahun 2019\"},{\"id\":\"tolerance_limit\",\"label\":\"Tolerance Limit (Syarat Maksimum)\",\"type\":\"text\",\"placeholder\":\"Contoh: Maks. 250 mg\\/kg\"},{\"id\":\"acceptance_limit\",\"label\":\"Acceptance Limit\",\"type\":\"text\"},{\"id\":\"tanggal_laporan\",\"label\":\"Tanggal Laporan\",\"type\":\"date\"}]}]}','Aktif');
INSERT INTO `form_templates` (`kode_template`,`nama_template`,`kategori`,`komoditi`,`skema_form`,`status`) VALUES ('PANG-KIM-AAS','LCP AAS Pangan - Cemaran Logam (As, Cd, Hg, Pb, Sn)','Kimia','pangan','{\"kode_dokumen\":\"POM-06.02\\/CFM.01\\/SOP.01\\/F.01A.14\",\"judul\":\"LAMPIRAN CATATAN PENGUJIAN - SPEKTROFOTOMETRI SERAPAN ATOM (AAS)\",\"kategori\":\"Kimia\",\"sections\":[{\"id\":\"kondisi_alat_aas\",\"title\":\"Kondisi Instrumen AAS & Identitas Elemen Logam\",\"description\":\"Formulir resmi POM-06.02\\/CFM.01\\/SOP.01\\/F.01A.14. Pilih Elemen Logam untuk mengisi otomatis Wavelength, Metode AAS, Pustaka, serta LOD\\/LOQ referensi.\",\"fields\":[{\"id\":\"elemen_logam\",\"label\":\"Elemen Logam Target\",\"type\":\"select\",\"options\":[\"As\",\"Cd\",\"Hg\",\"Pb\",\"Sn\"],\"default\":\"Pb\"},{\"id\":\"merk_alat\",\"label\":\"Merk Alat AAS\",\"type\":\"text\",\"default\":\"Analytic Jena\"},{\"id\":\"tipe_seri\",\"label\":\"Tipe \\/ Seri\",\"type\":\"text\",\"default\":\"ContraAA800D\"},{\"id\":\"wavelength\",\"label\":\"Wavelength\",\"type\":\"text\",\"default\":\"224,6 nm\"},{\"id\":\"metode_aas\",\"label\":\"Metode AAS\",\"type\":\"select\",\"options\":[\"Graphite Furnace Atomizer\",\"Hydride Vapour Generator\",\"Flame AAS\"],\"default\":\"Graphite Furnace Atomizer\"},{\"id\":\"baku_nama\",\"label\":\"Baku Pembanding\",\"type\":\"text\",\"default\":\"Lead Standard Solution 1000 mg\\/L\"},{\"id\":\"pelarut\",\"label\":\"Pelarut \\/ Modifier\",\"type\":\"text\",\"default\":\"HNO3 0,1 N dengan modifier\"},{\"id\":\"larutan_pereduksi\",\"label\":\"Larutan Pereduksi\",\"type\":\"text\",\"default\":\"-\"},{\"id\":\"linieritas_baku\",\"label\":\"Linieritas Baku\",\"type\":\"text\",\"default\":\"terlampir\"}]},{\"id\":\"tabel_baku_pembanding_kurva\",\"title\":\"1. Baku Pembanding & Regresi Kurva Baku AAS\",\"description\":\"Input Konsentrasi (µg\\/L \\/ ppb) dan Serapan\\/Absorbansi untuk Blanko Baku & 6 titik Baku Kerja. Sistem menghitung y = bx + a, r (≥ 0,99), Sy\\/x, Vx0 (≤ 0,05), dan Grafik Kurva Baku.\",\"fields\":[{\"id\":\"blanko_baku_serapan\",\"label\":\"Serapan Blanko Baku\",\"type\":\"number\",\"step\":\"any\",\"default\":\"0\"},{\"id\":\"tabel_baku_kurva\",\"label\":\"Tabel Baku Kerja AAS\",\"type\":\"table\",\"columns\":[{\"id\":\"tahap\",\"label\":\"Tahap\",\"type\":\"text\",\"readonly\":true},{\"id\":\"faktor_pengenceran\",\"label\":\"Faktor Pengenceran\",\"type\":\"text\"},{\"id\":\"konsentrasi\",\"label\":\"Konsentrasi (Xi)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"respon_puncak\",\"label\":\"Serapan \\/ Absorbansi (Yi)\",\"type\":\"number\",\"step\":\"any\"}],\"default_rows\":[{\"tahap\":\"Baku 1\",\"faktor_pengenceran\":\"0.05\\/50*0.5\\/50\",\"konsentrasi\":\"10\",\"respon_puncak\":\"\"},{\"tahap\":\"Baku 2\",\"faktor_pengenceran\":\"0.05\\/50*1\\/50\",\"konsentrasi\":\"20\",\"respon_puncak\":\"\"},{\"tahap\":\"Baku 3\",\"faktor_pengenceran\":\"0.05\\/50*2\\/50\",\"konsentrasi\":\"40\",\"respon_puncak\":\"\"},{\"tahap\":\"Baku 4\",\"faktor_pengenceran\":\"0.05\\/50*3\\/50\",\"konsentrasi\":\"60\",\"respon_puncak\":\"\"},{\"tahap\":\"Baku 5\",\"faktor_pengenceran\":\"0.05\\/50*4\\/50\",\"konsentrasi\":\"80\",\"respon_puncak\":\"\"},{\"tahap\":\"Baku 6\",\"faktor_pengenceran\":\"0.05\\/50*5\\/50\",\"konsentrasi\":\"100\",\"respon_puncak\":\"\"}]},{\"id\":\"regresi_slope\",\"label\":\"Slope (b)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"regresi_intercept\",\"label\":\"Intercept (a)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"regresi_r\",\"label\":\"Corr. Coeff (r)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"sy_x\",\"label\":\"SD Residual (Sy\\/x)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"vx0\",\"label\":\"Vx0 (Syarat ≤ 0,05)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"syarat_r\",\"label\":\"Syarat Keberterimaan r\",\"type\":\"text\",\"default\":\"≥ 0,99\"}]},{\"id\":\"tabel_zat_uji_pangan\",\"title\":\"2. Zat Uji (Sampel Tanpa Spike - 2 Bagian)\",\"description\":\"Input penimbangan (g), faktor pengenceran (mis. 50 atau 50\\/1*50), dan Serapan. Rumus Kadar (mg\\/kg) = (Konsentrasi x Fp x 10^-3) \\/ W(g).\",\"fields\":[{\"id\":\"blanko_sampel_serapan\",\"label\":\"Serapan Blanko Sampel\",\"type\":\"number\",\"step\":\"any\",\"default\":\"0\"},{\"id\":\"tabel_zat_uji\",\"label\":\"Tabel Penimbangan & Pengukuran Zat Uji (Duplo)\",\"type\":\"table\",\"columns\":[{\"id\":\"tahap\",\"label\":\"Zat Uji\",\"type\":\"text\",\"readonly\":true},{\"id\":\"wadah_zat\",\"label\":\"Wadah+Zat (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"wadah_sisa\",\"label\":\"Wadah+Sisa (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"bobot_bersih\",\"label\":\"Bobot Zat (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"faktor_pengenceran\",\"label\":\"Faktor Pengenceran\",\"type\":\"text\"},{\"id\":\"respon_puncak\",\"label\":\"Serapan (Absorbansi)\",\"type\":\"number\",\"step\":\"any\"}],\"default_rows\":[{\"tahap\":\"1. Uji-01\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"50\",\"respon_puncak\":\"\"},{\"tahap\":\"2. Uji-02\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"50\",\"respon_puncak\":\"\"}]}]},{\"id\":\"tabel_spiked_sample_pangan\",\"title\":\"3. Spiked Sample (Duplo)\",\"description\":\"Opsional jika dilakukan uji spike duplo.\",\"fields\":[{\"id\":\"spike_vol_ml\",\"label\":\"Volume Baku Ditambahkan (mL)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"spike_sumber_konsentrasi\",\"label\":\"Konsentrasi Baku Penambah (mg\\/L)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"spike_berat_sampel\",\"label\":\"Berat Sampel Target Spike (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"kadar_baku_ditambahkan\",\"label\":\"Kadar Baku Ditambahkan (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"tabel_spiked_sample\",\"label\":\"Tabel Spiked Sample (Duplo)\",\"type\":\"table\",\"columns\":[{\"id\":\"tahap\",\"label\":\"Spiked Sample\",\"type\":\"text\",\"readonly\":true},{\"id\":\"wadah_zat\",\"label\":\"Wadah+Zat (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"wadah_sisa\",\"label\":\"Wadah+Sisa (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"bobot_bersih\",\"label\":\"Bobot Zat (g)\",\"type\":\"number\",\"step\":\"any\"},{\"id\":\"faktor_pengenceran\",\"label\":\"Faktor Pengenceran\",\"type\":\"text\"},{\"id\":\"respon_puncak\",\"label\":\"Serapan (Absorbansi)\",\"type\":\"number\",\"step\":\"any\"}],\"default_rows\":[{\"tahap\":\"Spiked 1\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"50\",\"respon_puncak\":\"\"},{\"tahap\":\"Spiked 2\",\"wadah_zat\":\"\",\"wadah_sisa\":\"\",\"bobot_bersih\":\"\",\"faktor_pengenceran\":\"50\",\"respon_puncak\":\"\"}]}]},{\"id\":\"perhitungan_pangan_aas\",\"title\":\"Perhitungan Kadar Cemaran Logam, RPD, & LOD\\/LOQ Referensi Otomatis\",\"description\":\"LOD & LOQ ditarik otomatis dari tabel referensi master_lod_loq_logam berdasarkan Elemen Logam terpilih.\",\"fields\":[{\"id\":\"x1_sampel\",\"label\":\"Konsentrasi Uji-1 (ppb)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"x2_sampel\",\"label\":\"Konsentrasi Uji-2 (ppb)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar1_sampel\",\"label\":\"Kadar Cemaran Logam 1 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"kadar2_sampel\",\"label\":\"Kadar Cemaran Logam 2 (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"rata_kadar_sampel\",\"label\":\"Rata-rata Kadar Cemaran Logam (mg\\/kg)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"recovery_1\",\"label\":\"Recovery 1 (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"recovery_2\",\"label\":\"Recovery 2 (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"nilai_rpd\",\"label\":\"RPD \\/ RSD (%)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"syarat_horwitz\",\"label\":\"Syarat RPD (1\\/2 CV Horwitz %)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"lod_nilai\",\"label\":\"LOD Referensi (Auto)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"lod_satuan\",\"label\":\"Satuan LOD\",\"type\":\"text\",\"default\":\"mg\\/kg\",\"readonly\":true},{\"id\":\"loq_nilai\",\"label\":\"LOQ Referensi (Auto)\",\"type\":\"number\",\"step\":\"any\",\"readonly\":true},{\"id\":\"loq_satuan\",\"label\":\"Satuan LOQ\",\"type\":\"text\",\"default\":\"mg\\/kg\",\"readonly\":true},{\"id\":\"ketidakpastian_teks\",\"label\":\"Hasil Uji ± Ketidakpastian\",\"type\":\"text\",\"placeholder\":\"Otomatis jika < LOD\"},{\"id\":\"decision_rule\",\"label\":\"Aturan Keputusan (Decision Rule)\",\"type\":\"select\",\"options\":[\"Simple Acceptance\",\"Guard Band\"],\"default\":\"Simple Acceptance\"}]},{\"id\":\"kesimpulan_legalitas_aas\",\"title\":\"Pustaka Persyaratan & Legalitas\",\"fields\":[{\"id\":\"pustaka_metode\",\"label\":\"Pustaka Metode\",\"type\":\"text\",\"default\":\"72\\/PA\\/MA-PPPOMN\\/18\"},{\"id\":\"pustaka_persyaratan\",\"label\":\"Pustaka Persyaratan\",\"type\":\"text\",\"default\":\"PerBPOM No. 9 Tahun 2022\"},{\"id\":\"tolerance_limit\",\"label\":\"Tolerance Limit (Syarat Maksimum)\",\"type\":\"text\",\"placeholder\":\"Contoh: Maks. 0,30 mg\\/kg\"},{\"id\":\"acceptance_limit\",\"label\":\"Acceptance Limit\",\"type\":\"text\"},{\"id\":\"tanggal_laporan\",\"label\":\"Tanggal Laporan\",\"type\":\"date\"}]}]}','Aktif');
