-- =============================================================================
-- LIMSKU Sync Database: Pangan Olahan (496) + LOD/LOQ Logam + LCP Pangan Part 1
-- Aman untuk merge antar-developer (tanpa bentrok Primary Key id form_templates)
-- =============================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 1. Tabel Referensi LOD & LOQ Logam (AAS)
DROP TABLE IF EXISTS `master_lod_loq_logam`;
CREATE TABLE `master_lod_loq_logam` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `elemen` varchar(20) NOT NULL,
  `nama_parameter` varchar(150) NOT NULL,
  `instrumen` varchar(50) NOT NULL DEFAULT 'AAS',
  `metode_aas` varchar(100) DEFAULT NULL,
  `wavelength` varchar(50) DEFAULT NULL,
  `baku_pembanding` varchar(150) DEFAULT NULL,
  `pelarut` varchar(255) DEFAULT NULL,
  `larutan_pereduksi` varchar(150) DEFAULT NULL,
  `pustaka_metode` varchar(100) DEFAULT NULL,
  `lod_nilai` decimal(12,6) NOT NULL,
  `loq_nilai` decimal(12,6) NOT NULL,
  `satuan` varchar(30) NOT NULL DEFAULT 'mg/kg',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_elemen_instrumen` (`elemen`,`instrumen`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Tabel Pedoman Pangan Olahan (496 data dari Adendum Lampiran 78)
TRUNCATE TABLE `master_metode_pangan_olahan`;

-- 3. Template LCP Pangan (tanpa hardcode id agar aman saat merge)
DELETE FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-01';
DELETE FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-02';
DELETE FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-03';
DELETE FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-AAS';

-- 4. Auto-mapping template_id berdasarkan kode_template (dinamis)
UPDATE `master_metode_pangan_olahan` SET `template_id` = (SELECT `id` FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-01' LIMIT 1) WHERE `bidang`='Kimia' AND (`metode_analisa` LIKE '%16/PA/13%' OR `metode_analisa` LIKE '%17/PA/13%' OR `parameter_uji` LIKE '%Sakarin%' OR `parameter_uji` LIKE '%Asesulfam%' OR `parameter_uji` LIKE '%Aspartam%');
UPDATE `master_metode_pangan_olahan` SET `template_id` = (SELECT `id` FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-02' LIMIT 1) WHERE `bidang`='Kimia' AND (`metode_analisa` LIKE '%08/PA/13%' OR `metode_analisa` LIKE '%19/PA/15%' OR `parameter_uji` LIKE '%Benzoat%' OR `parameter_uji` LIKE '%Sorbat%');
UPDATE `master_metode_pangan_olahan` SET `template_id` = (SELECT `id` FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-03' LIMIT 1) WHERE `bidang`='Kimia' AND (`metode_analisa` LIKE '%53/PA/16%' OR `parameter_uji` LIKE '%Siklamat%');
UPDATE `master_metode_pangan_olahan` SET `template_id` = (SELECT `id` FROM `form_templates` WHERE `kode_template` = 'PANG-KIM-AAS' LIMIT 1) WHERE `bidang`='Kimia' AND `template_id` IS NULL AND (`metode_analisa` LIKE '%AAS%' OR `metode_analisa` LIKE '%16/PA%' OR `metode_analisa` LIKE '%72/PA%' OR `metode_analisa` LIKE '%121/PA%' OR `metode_analisa` LIKE '%18/PA%' OR `metode_analisa` LIKE '%11/PA%');

SET FOREIGN_KEY_CHECKS = 1;

